  "Ki vagyok?":
    "Wer bin ich?",
  "2018 óta készítek videókat PrepperPapa néven a felkészülésről. Hiszem, hogy a keresztény értékek és a jó gyakorlati eszközök együtt segítenek abban, hogy könnyebben vegyük a mindennapok kihívásait, ezért a célom az, hogy fényt hozzak az életedbe, lelkiekben és a szó szoros értelmében is.":
    "Seit 2018 mache ich unter dem Namen PrepperPapa Videos über Krisenvorsorge. Ich glaube, dass christliche Werte und gute praktische Ausrüstung zusammen helfen, die Herausforderungen des Alltags leichter zu nehmen. Deshalb ist es mein Ziel, Licht in dein Leben zu bringen, geistlich und auch im wörtlichen Sinn.",
  "Lámpákat, késeket, táskákat és energiaforrásokat tesztelek valós használatban, és ha valami nem vált be, azt is elmondom. Nem világvége-hangulatot árulok, hanem azt a néhány dolgot mutatom meg, ami egy áramszünetben, egy viharban vagy egy túrán tényleg számít.":
    "Ich teste Lampen, Messer, Taschen und Energiequellen im echten Einsatz, und wenn sich etwas nicht bewährt hat, sage ich das auch. Ich verkaufe keine Weltuntergangsstimmung, sondern zeige die paar Dinge, die bei einem Stromausfall, einem Unwetter oder auf einer Tour wirklich zählen.",
  "Felkészülés józan ésszel, magyar valóságra.":
    "Vorsorge mit gesundem Menschenverstand, für die ungarische Realität.",
