    "Die Daten kommen aus dem Haushalt, pro Person: Blutgruppe, Allergie, Medikament, Krankheit, die eigene Telefonnummer und der Notfallkontakt (Name und Telefon). Wo noch kein Kontakt angegeben ist, verwenden wir den Kontakt deines eigenen Ausweises.",
