  "Teszt funkció: beállíthatsz egy fizetős csomagot, és az app úgy viselkedik, mintha azt vásárolták volna meg. Csak ezen a készüléken, csak a felületen. A valódi feloldásaid megmaradnak, kikapcsolva visszaáll minden.":
    "Testfunktion: Du kannst ein kostenpflichtiges Paket einstellen, und die App verhält sich so, als wäre es gekauft worden. Nur auf diesem Gerät, nur in der Oberfläche. Deine echten Freischaltungen bleiben erhalten, beim Ausschalten wird alles zurückgesetzt.",
