  "A megadott wattórából 10 százalékot levonunk átalakítási veszteségre.":
    "Von den angegebenen Wattstunden ziehen wir 10 Prozent für Umwandlungsverluste ab.",
  "A savas akkut csak félig szabad lemeríteni, különben tönkremegy, és az átalakító is elvisz 15 százalékot. Ezért a névlegesnek nagyjából 42 százalékával számolunk.":
    "Eine Blei-Säure-Batterie darf man nur zur Hälfte entladen, sonst geht sie kaputt, und der Wechselrichter nimmt auch noch 15 Prozent. Deshalb rechnen wir mit etwa 42 Prozent des Nennwerts.",
  "A LiFePO4-et 80 százalékig le lehet meríteni (a savasat csak felére), az átalakító 10 százalékot visz.":
    "LiFePO4 kann man bis 80 Prozent entladen (Blei-Säure nur zur Hälfte), der Wechselrichter nimmt 10 Prozent.",
  "A tárolt energiából kb. 10 százalékot elvisz az átalakítás, ezért nem a teljes wattóra használható fel.":
    "Von der gespeicherten Energie nimmt die Umwandlung ca. 10 Prozent, daher ist nicht die volle Wattstundenzahl nutzbar.",
