  "Rejtőzködés, fekvés, olvasás. Ennyivel nem hízol és nem is fogysz gyorsan, de a fejed tiszta marad.":
    "Verstecken, Liegen, Lesen. Damit nimmst du weder zu noch schnell ab, aber dein Kopf bleibt klar.",
  "Járkálás, ház körüli teendők. Ez a nemzetközi vészhelyzeti tervezés alapszáma is.":
    "Herumgehen, Arbeiten ums Haus. Das ist auch die Grundzahl der internationalen Notfallplanung.",
  "Favágás, sáncolás, teherrel gyaloglás, hideg. Ez a szám gyorsan elviszi a készletet -- éppen ezért érdemes előre számolni vele.":
    "Holzhacken, Schanzen, Gehen mit Last, Kälte. Diese Zahl frisst den Vorrat schnell auf -- gerade deshalb lohnt es sich, vorher damit zu rechnen.",
