  "egység":
    "Einheit",
  "Engedély nélküli, 4 watt AM/FM (SSB-n 12). Nagy antennát kíván, de a hosszú hullám jobban hajlik a domb mögé, mint bármelyik kézirádió.":
    "Genehmigungsfrei, 4 Watt AM/FM (SSB 12). Braucht eine große Antenne, aber die lange Welle beugt sich besser hinter den Hügel als jedes Handfunkgerät.",
  "ENGEDÉLYKÖTELES: vizsga és hívójel kell hozzá. Vészhelyzetben az életveszély elhárítására a törvény enged kivételt, de arra épülő tervet ne csinálj -- a vizsga előre megszerezhető.":
    "GENEHMIGUNGSPFLICHTIG: Prüfung und Rufzeichen nötig. Im Notfall erlaubt das Gesetz eine Ausnahme zur Abwendung von Lebensgefahr, aber bau keinen Plan darauf -- die Prüfung kann man vorher ablegen.",
  "ENGEDÉLYKÖTELES. Itt NEM a rálátás dönt: nappal 100-400 km-re, éjjel akár több ezerre visz az ionoszféráról visszaverődve. Ezt a kalkulátor nem modellezi -- lásd a figyelmeztetést az eredménynél.":
    "GENEHMIGUNGSPFLICHTIG. Hier entscheidet NICHT die Sichtverbindung: Tagsüber 100-400 km, nachts bis zu mehreren tausend, über die Ionosphäre reflektiert. Das bildet der Rechner nicht ab -- siehe Warnung beim Ergebnis.",
  "ENGEDÉLYKÖTELES. Éjszakai sáv, a környék (50-300 km) megbízható lefedésére a legjobb -- ez a klasszikus \"megyényi\" összeköttetés.":
    "GENEHMIGUNGSPFLICHTIG. Nachtband, am besten für die zuverlässige Abdeckung der Umgebung (50-300 km) -- die klassische \"landkreisweite\" Verbindung.",
  "Mező, tópart, autópálya. Itt a rálátás a korlát, nem a terep.":
    "Feld, Seeufer, Autobahn. Hier begrenzt die Sichtverbindung, nicht das Gelände.",
  "A domb mögé a jel behajlik, de gyengülve. Egy dombtetőre felsétálni többet ér, mint tízszeres teljesítmény.":
    "Hinter den Hügel beugt sich das Signal, aber abgeschwächt. Auf eine Hügelkuppe zu gehen bringt mehr als zehnfache Leistung.",
  "A lombozat a rövid hullámot nyeli el jobban, ezért itt a 70 centi a leggyengébb.":
    "Laub schluckt kurze Wellen stärker, deshalb ist hier 70 cm am schwächsten.",
  "Itt fordul meg a sorrend: a 70 centi jobban jut át épületek között, a CB-nek meg antennája sincs hova.":
    "Hier kehrt sich die Reihenfolge um: 70 cm kommt besser zwischen Gebäuden durch, und für CB ist nicht mal Platz für die Antenne.",
  "Völgyben ülve a rálátás nulla. Itt a megoldás nem a watt, hanem az átjátszó vagy a gerincre feljutás.":
    "Im Tal ist die Sichtverbindung null. Die Lösung ist hier nicht Watt, sondern ein Relais oder der Weg auf den Kamm.",
