  "méter emelkedés.":
    "Meter Anstieg.",
  "Az emelkedés minden hatszáz métere egy órát ad hozzá. Most indulva":
    "Alle sechshundert Meter Anstieg kommt eine Stunde dazu. Wenn du jetzt losgehst,",
  "-kor érnél oda.":
    " Uhr wärst du dort.",
  "Pihenő nincs benne. Hosszabb úton számolj óránként tíz perccel, és étkezéssel.":
    "Pausen sind nicht eingerechnet. Auf längeren Strecken rechne zehn Minuten pro Stunde dazu, plus Essen.",
