  "Buzgó forrás":
    "Sprudelnd kochen",
  "— kétezer méter felett vagy, ott hosszabb kell, mert alacsonyabb a forráspont.":
    "— du bist über zweitausend Metern, dort braucht es länger, weil der Siedepunkt niedriger ist.",
  "Hagyd kihűlni fedő alatt.":
    "Mit Deckel abkühlen lassen.",
  "Ha nem tudsz forralni: hipó":
    "Wenn du nicht abkochen kannst: Chlorbleiche",
