  "Fax: kép átküldése hangban, rádión is. Ugyanaz a gomb indít és állít.": "Fax: ein Bild im Ton übertragen, auch über Funk. Dieselbe Taste startet und stoppt.",
  "A kód a fiókodhoz tartozik, és legfeljebb két készüléken használhatod. A feloldott modulok offline is működnek, semmi nem zár le. Ha kódot kaptál, itt válthatod be.": "Der Code gehört zu deinem Konto und du kannst ihn auf bis zu zwei Geräten nutzen. Freigeschaltete Module funktionieren auch offline, nichts wird gesperrt. Wenn du einen Code bekommen hast, kannst du ihn hier einlösen.",
  "Feloldva ✓ A kód a fiókodhoz tartozik, legfeljebb két készüléken.": "Freigeschaltet ✓ Der Code gehört zu deinem Konto, auf bis zu zwei Geräten.",
