  "Koppints a térképre pont hozzáadásához (menedék, víz, találkozópont). Ha ott": "Tippe auf die Karte, um einen Punkt hinzuzufügen (Unterkunft, Wasser, Treffpunkt). Wenn du dort",
  "állsz": "stehst",
  ", ahová a pont való, a": ", wo der Punkt hin soll, ist",
  "pontosabb: az a GPS-edet használja, nem azt, ahová az ujjad ér. A": "genauer: Er nutzt dein GPS, nicht die Stelle, die dein Finger trifft. Die Schaltfläche",
  "a mostani koordinátádat adja tovább üzenetben, a": "gibt deine aktuellen Koordinaten per Nachricht weiter, und",
  "Pontok kimentése": "Punkte exportieren",
  "pedig GPX-fájlba menti mindet, amit a térkép- és navigációs programok beolvasnak. A pontok és a jelenlegi pozíció helyben tárolódnak. A": "speichert sie alle in eine GPX-Datei, die Karten- und Navigationsprogramme lesen. Die Punkte und die aktuelle Position werden lokal gespeichert. Die Schaltfläche",
  "a most látható kivágást menti a készülékre, három nagyítási szinten — utána térerő nélkül is megvan.": "speichert den gerade sichtbaren Ausschnitt auf das Gerät, in drei Zoomstufen — danach ist er auch ohne Empfang verfügbar.",
  "Rendszeres gyógyszerek": "Dauermedikamente",
  "Rendszeres gyógyszer": "Dauermedikament",
