  "Vészhelyzeti kontakt (név, telefon)": "Notfallkontakt (Name, Telefon)",
  "QR-kód generálása": "QR-Code erzeugen",
  "A QR a fenti adatokat kódolja. Kihelyezheted a zárolt képernyődre vagy kinyomtatva a hátizsákodba.": "Der QR-Code enthält die obigen Daten. Du kannst ihn auf deinen Sperrbildschirm legen oder ausgedruckt in den Rucksack stecken.",
  "Mindenkinek, akinek van profilja a Háztartásnál. Az adat onnan jön: vércsoport, allergia, gyógyszer, betegség. A vészhelyzeti kontakt a fenti közös mezőből.": "Für alle, die ein Profil unter „Haushalt\" haben. Die Daten kommen von dort: Blutgruppe, Allergie, Medikamente, Erkrankungen. Der Notfallkontakt stammt aus dem gemeinsamen Feld oben.",
  "Még nincs profil. A Háztartásnál vedd fel, kik vagytok — mindenki kap egy kártyát.": "Noch kein Profil vorhanden. Trag unter „Haushalt\" ein, wer ihr seid — jeder bekommt eine Karte.",
  "Mind nyomtatása": "Alle drucken",
  "Megtérő ima": "Bekehrungsgebet",
