  "Következő ›": "Weiter ›",
  "A kiemeléseidhez előbb töltsd le a Bibliát.": "Für deine Markierungen lade zuerst die Bibel herunter.",
  "A teljes Károli-fordítás egyszer letöltődik (kb. 4 MB), és utána internet nélkül is elérhető marad.": "Die vollständige Károli-Übersetzung wird einmal heruntergeladen (ca. 4 MB) und bleibt danach auch ohne Internet verfügbar.",
  "Vészhelyzeti igék": "Bibelverse für Notlagen",
  "Próféciák": "Prophezeiungen",
  "Kiemeléseim": "Meine Markierungen",
  "Token tárca": "Token-Wallet",
  "Titkos kódok PIN mögött, helyben tárolva. Ugyanaz a PIN nyitja, mint az Irattárcát.": "Geheime Codes hinter einer PIN, lokal gespeichert. Es öffnet dieselbe PIN wie die Dokumentenmappe.",
  "Új PIN (4-6 számjegy)": "Neue PIN (4-6 Ziffern)",
  "TESZT ÜZEMMÓD: a PIN most": "TESTMODUS: Die PIN ist derzeit",
  ", előre kitöltve. Éles használat előtt ez kikerül, és saját PIN-t adsz meg.": ", vorausgefüllt. Vor dem echten Einsatz wird das entfernt, und du legst eine eigene PIN fest.",
  "A web-demó nem ad operációs rendszer szintű titkosítást: a kódok a böngésző tárolójában vannak. Valódi seed-mondatot vagy éles banki kódot majd a végleges appba tegyél (biometrikus zár, titkosított tár). Itt a folyamatot próbáld ki. A teljes mentésbe ez a rész SOSEM kerül bele.": "Die Web-Demo bietet keine Verschlüsselung auf Betriebssystemebene: Die Codes liegen im Speicher des Browsers. Eine echte Seed-Phrase oder einen echten Bankcode leg erst in die finale App (biometrische Sperre, verschlüsselter Speicher). Hier probierst du nur den Ablauf aus. In die vollständige Sicherung kommt dieser Teil NIEMALS.",
  "Súgó — hogyan fizetek, hogyan kérek": "Hilfe — wie ich zahle, wie ich anfordere",
  "Fizetés, három lépés.": "Zahlung, drei Schritte.",
  "1. Ő megmutatja az azonosító-QR-jét, vagy küld egy kérést. Te beolvasod: ettől nálad kitöltődik az űrlap.": "1. Er zeigt seinen Identitäts-QR-Code oder schickt eine Anfrage. Du scannst ihn: Damit füllt sich bei dir das Formular.",
  "2. Megadod az összeget és hogy miért, majd Fizetés elkészítése. A telefonod aláírja, és mutat egy QR-t.": "2. Du gibst den Betrag und den Zweck an, dann „Zahlung vorbereiten\". Dein Telefon signiert sie und zeigt einen QR-Code.",
  "Ő beolvassa ezt a QR-t.": "Er scannt diesen QR-Code.",
  "Az érték ekkor kerül át hozzá — a telefonja ellenőrzi az aláírást, és jóváírja.": "Erst dann geht der Wert zu ihm über — sein Telefon prüft die Signatur und schreibt ihn gut.",
  "Pénzkérés.": "Geld anfordern.",
  "Kérek gírát, beírod mennyit és miért, kapsz egy QR-t. Ő beolvassa, és nála kitöltve áll a fizetés, csak jóvá kell hagynia.": "Fordere Gira an, gib ein, wie viel und wofür, und du bekommst einen QR-Code. Er scannt ihn, und bei ihm steht die Zahlung ausgefüllt bereit — er muss sie nur bestätigen.",
  "Miért két beolvasás?": "Warum zweimal scannen?",
  "Mert az ő kódja csak azt mondja meg, kinek és mennyit. Az értéket a te aláírásod viszi át, és az a te QR-edben van. Amíg ő nem olvasta be, a tétel nálad „átadásra vár” jelöléssel áll.": "Weil sein Code nur sagt, an wen und wie viel. Den Wert überträgt deine Signatur, und die steckt in deinem QR-Code. Solange er ihn nicht gescannt hat, steht der Eintrag bei dir mit der Markierung „wartet auf Übergabe”.",
  "Minden a két telefon között megy, kamerával és képernyővel. Se szerver, se térerő.": "Alles läuft zwischen den beiden Telefonen, über Kamera und Bildschirm. Weder Server noch Empfang.",
  "Van, ahol a böngésző nem tud QR-t olvasni (jellemzően iPhone Safari). Ilyenkor a Beillesztés szövegből gomb ugyanazt tudja: a fizetés elkészítése után a QR alatti Szöveg másolása gombbal átküldöd a tételt üzenetben, ő pedig a Beillesztés szövegből gombbal beveszi. Az ellenőrzés ugyanúgy megtörténik, az aláírás a szövegben is benne van.": "Manchmal kann der Browser keine QR-Codes lesen (typischerweise Safari auf dem iPhone). Dann kann die Schaltfläche „Aus Text einfügen\" dasselbe: Nach dem Vorbereiten der Zahlung schickst du den Eintrag mit „Text kopieren\" unter dem QR-Code als Nachricht, und er nimmt ihn mit „Aus Text einfügen\" an. Die Prüfung läuft genauso, die Signatur steckt auch im Text.",
  "a nevedben más nem tud fizetni (a titkos kulcs a telefonodon marad), és egy aláírt tétel utólag nem módosítható észrevétlenül.": "niemand anders kann in deinem Namen zahlen (der geheime Schlüssel bleibt auf deinem Telefon), und ein signierter Eintrag lässt sich nachträglich nicht unbemerkt ändern.",
  "offline a kettős költést megelőzni nem lehet. Ha valaki ugyanazt a gírát két embernek adja, az akkor derül ki, amikor a két tétel találkozik — és a saját aláírása bizonyítja. Ezért érdemes időnként összefésülni a könyveket a közösségben.": "offline lässt sich doppeltes Ausgeben nicht verhindern. Wenn jemand dieselbe Gira zwei Personen gibt, kommt das heraus, sobald die beiden Einträge zusammentreffen — und seine eigene Signatur beweist es. Deshalb lohnt es sich, die Bücher in der Gemeinschaft von Zeit zu Zeit abzugleichen.",
  "Rekesz": "Fach",
  "Kripto-kulcsok": "Krypto-Schlüssel",
  "Új bejegyzés": "Neuer Eintrag",
  "Seed-mondatnál a papír-másolat nem elavult ötlet: egy elveszett vagy letörölt telefon a kulcsot is viszi. Amit ide beírsz, azt tartsd meg máshol is.": "Bei einer Seed-Phrase ist die Papierkopie keine veraltete Idee: Ein verlorenes oder gelöschtes Telefon nimmt auch den Schlüssel mit. Was du hier einträgst, bewahre auch anderswo auf.",
  "PIN-nel védett helyi tároló okmányokhoz (szig, jogosítvány, TAJ, biztosítás, forgalmi).": "PIN-geschützter lokaler Speicher für Ausweise (Personalausweis, Führerschein, Versichertenkarte, Versicherung, Fahrzeugschein).",
  "A PIN és a dokumentumok CSAK ezen az eszközön, a böngésződben tárolódnak — a vészkártyával ellentétben ezt csak te nyithatod meg. Figyelem: a web-demó nem nyújt OS-szintű titkosítást; VALÓDI okmányokat majd a végleges appba tölts (biometrikus zár, titkosított tár). Itt a folyamatot teszteld.": "Die PIN und die Dokumente werden NUR auf diesem Gerät, in deinem Browser gespeichert — anders als bei der Notfallkarte kannst nur du sie öffnen. Achtung: Die Web-Demo bietet keine Verschlüsselung auf Betriebssystemebene; ECHTE Ausweise lade erst in die finale App (biometrische Sperre, verschlüsselter Speicher). Hier teste nur den Ablauf.",
  "Szűrés: kinek az iratait mutassuk": "Filter: wessen Dokumente sollen angezeigt werden",
  "Új dokumentum": "Neues Dokument",
  "Ehhez a dokumentumhoz: kié? Személy, állat vagy jármű. Ha egyiket sem jelölöd, közösként mentjük.": "Zu diesem Dokument: Wem gehört es? Person, Tier oder Fahrzeug. Wenn du nichts auswählst, speichern wir es als gemeinsam.",
  "Magyar": "Magyar",
  "véglegesen": "dauerhaft",
  "szól erre a készülékre, nincs lejárata és nincs megújítás. Ha kódot kaptál, itt válthatod be.": "gilt für dieses Gerät, ohne Ablauf und ohne Verlängerung. Wenn du einen Code bekommen hast, kannst du ihn hier einlösen.",
  "Kód beváltása": "Code einlösen",
