  "PrepperPapa — vészhelyzeti prepper eszköztár.": "PrepperPapa — Werkzeugkasten für Notlagen.",
  "Verzió:": "Version:",
  "Web-demo a gyors próbához. A végleges app: Flutter, Google Play.": "Web-Demo zum schnellen Ausprobieren. Die finale App: Flutter, Google Play.",
  "Teljes fejadattal számol: 3 liter fő/nap. Ez a helyben maradáshoz és az autós úthoz való — nyaraló, tábor, otthon.": "Rechnet mit der vollen Ration: 3 Liter pro Person und Tag. Das ist für das Bleiben vor Ort und die Fahrt mit dem Auto gedacht — Ferienhaus, Lager, Zuhause.",
  "Ki tartozik a háztartáshoz és hol vannak a helyszíneid. A készültségi számítás ebből dolgozik.": "Wer zum Haushalt gehört und wo deine Orte sind. Die Bereitschaftsberechnung arbeitet mit diesen Daten.",
  "Még nincs családtag felvéve.": "Noch keine Familienmitglieder eingetragen.",
