  "Még nincs jármű felvéve. Autó, kisbusz, lakókocsi vagy hajó lehet.": "Noch kein Fahrzeug erfasst. Es kann ein Auto, ein Kleinbus, ein Wohnwagen oder ein Boot sein.",
  "Még nincs helyszín felvéve. Alapesetben az otthon az első.": "Noch keine Orte eingetragen. Standardmäßig steht das Zuhause an erster Stelle.",
