  "Ma éjjel gyakorlatilag nincs holdfény, számolj lámpával.": "Heute Nacht gibt es praktisch kein Mondlicht, rechne mit einer Lampe.",
  "Közepes holdfény: nyílt terepen segít, erdőben nem.": "Mittleres Mondlicht: Im offenen Gelände hilft es, im Wald nicht.",
  "mérés az elmúlt 48 órából. Ezen a készüléken a böngésző nem éri el a légnyomás-szenzort, ezért kézzel viszed be; a telefonos appban magától fog mérni.": "Messungen aus den letzten 48 Stunden. Auf diesem Gerät hat der Browser keinen Zugriff auf den Luftdrucksensor, daher gibst du die Werte von Hand ein; in der Telefon-App wird automatisch gemessen.",
  "Ez a böngésző nem tud értesítést megjeleníteni": "Dieser Browser kann keine Benachrichtigungen anzeigen",
