  "Indítás": "Starten",
  "Számolók": "Rechner",
  "Nem sikerült a helymeghatározás:": "Die Standortbestimmung ist fehlgeschlagen:",
  "A térkép utolsó nézete alapján is tudok számolni, nyisd meg egyszer a térképet.": "Ich kann auch anhand der letzten Kartenansicht rechnen — öffne die Karte wenigstens einmal.",
  "Ehhez előbb le kell tölteni a Biblia szövegét (a Biblia képernyőn, egyszer).": "Dafür muss zuerst der Bibeltext heruntergeladen werden (auf dem Bibel-Bildschirm, einmalig).",
  "‹ Könyvek": "‹ Bücher",
  "Ószövetség": "Altes Testament",
  "Újszövetség": "Neues Testament",
  "300+ találat (az elsőket mutatom)": "300+ Treffer (die ersten werden angezeigt)",
  "találat": "Treffer",
  "Nincs találat erre:": "Keine Treffer für:",
  "fejezet": "Kapitel",
  "Egész fejezet": "Ganzes Kapitel",
  "Még nincs kiemelt vers. Nyiss meg egy fejezetet, és koppints egy versre.": "Noch keine markierten Verse. Öffne ein Kapitel und tippe auf einen Vers.",
  "Klasszikus prófétai szakaszok. Az értelmezésük felekezetenként eltér — itt a szöveg áll, magyarázat nélkül.": "Klassische prophetische Abschnitte. Ihre Auslegung unterscheidet sich je nach Konfession — hier steht nur der Text, ohne Erklärung.",
  "Amikor félsz": "Wenn du Angst hast",
  "Amikor nem tudod, mit tegyél": "Wenn du nicht weißt, was du tun sollst",
  "Amikor kifogytál az erődből": "Wenn deine Kraft am Ende ist",
  "Amikor veszteség ér": "Wenn dich ein Verlust trifft",
  "Amikor félted a családodat": "Wenn du um deine Familie fürchtest",
  "Amikor az ellátás a kérdés": "Wenn es um die Versorgung geht",
  "Amikor másokon kell segítened": "Wenn du anderen helfen musst",
  "Amikor a kitartás a tét": "Wenn es auf Ausdauer ankommt",
  "Jézus beszéde az utolsó időkről": "Die Rede Jesu über die letzten Zeiten",
  "Dániel látomásai": "Die Visionen Daniels",
  "A szenvedő szolga és a Messiás": "Der leidende Knecht und der Messias",
  "Az utolsó idők jellemzői": "Merkmale der letzten Zeiten",
  "Ítélet és helyreállítás": "Gericht und Wiederherstellung",
  "teherbírás": "Tragfähigkeit",
  "Bogáncs": "Rex",
  "Belépés": "Anmelden",
  "Betöltés...": "Wird geladen...",
  "Betöltés…": "Wird geladen…",
  "Értem": "Verstanden",
  "Ha valaki ír egy szobádba, jelezzen a telefonod — akkor is, ha az app be van zárva.": "Wenn jemand in einen deiner Räume schreibt, soll dein Telefon sich melden — auch wenn die App geschlossen ist.",
  "Ehhez tudni kell, hol vagy. Nyomd meg a Mérés a helyzetemre gombot.": "Dafür muss bekannt sein, wo du bist. Drücke die Schaltfläche „Für meinen Standort berechnen\".",
  "Nézd meg most, mennyi üzemanyag van az autóban. Ha kevesebb mint fél tank, tankolj fel a héten, és onnantól tartsd ezt a szintet. Ez az egyetlen szokás, ami pénzbe nem kerül, mert azt a benzint úgyis megvennéd, csak korábban.": "Schau jetzt nach, wie viel Kraftstoff im Auto ist. Wenn es weniger als ein halber Tank ist, tanke diese Woche voll und halte dieses Niveau danach. Das ist die einzige Gewohnheit, die kein Geld kostet, denn dieses Benzin würdest du ohnehin kaufen — nur eben früher.",
  "Tudástár — Közlekedés és mobilitás": "Wissensbasis — Verkehr und Mobilität",
  "A lista a családtagjaidból áll össze, akiket a Háztartásnál vettél fel.": "Die Liste setzt sich aus deinen Familienmitgliedern zusammen, die du unter „Haushalt\" eingetragen hast.",
  "A dokumentumok a telefonodon maradnak. Nem megy belőlük semmi sehova, felhőbe sem.": "Die Dokumente bleiben auf deinem Telefon. Nichts davon geht irgendwohin, auch nicht in die Cloud.",
  "A gomb be- és kikapcsol. Ugyanaz a gomb indítja az adást és állítja meg — nincs külön Állj.": "Die Taste schaltet ein und aus. Dieselbe Taste startet das Senden und stoppt es — es gibt kein eigenes Stopp.",
  "A gyűrű a leggyengébb láncszemet mutatja, nem az átlagot. Egy hiányzó dolog lehúzza az egészet — és ez szándékos.": "Der Ring zeigt das schwächste Glied, nicht den Durchschnitt. Eine fehlende Sache zieht das Ganze herunter — und das ist Absicht.",
  "A vétel és az adás ugyanazzal a gombbal kapcsol. Amíg megy, hagyd a telefont nyugton.": "Empfang und Senden schalten mit derselben Taste. Solange es läuft, lass das Telefon in Ruhe.",
  "Egy témán belül két réteg van. Az alapréteg mindenkinek elérhető, ingyen.": "Innerhalb eines Themas gibt es zwei Ebenen. Die Basisebene ist für alle zugänglich, kostenlos.",
  "Ezt látja az, aki megtalálja a telefonodat. Csak azt írd bele, amit egy idegen is láthat.": "Das sieht, wer dein Telefon findet. Schreib nur hinein, was auch ein Fremder sehen darf.",
  "Felveszed az azimutot, és a tájoló megmutatja a visszautat is — nem kell fejben tartanod.": "Du nimmst das Azimut auf, und die Orientierung zeigt dir auch den Rückweg — du musst ihn nicht im Kopf behalten.",
  "Itt veszed fel a családot. Innen jön a fejadag-számítás és a helyszínek listája is.": "Hier trägst du die Familie ein. Von hier kommen die Rationsberechnung und die Liste der Orte.",
  "Keresés szó szerint, és amit megjelölsz, azt könyvjelzővel bármikor visszatalálod.": "Wortgenaue Suche, und was du markierst, findest du jederzeit über das Lesezeichen wieder.",
  "Koppints a térképre, és ott új pontot veszel fel.": "Tippe auf die Karte, und dort wird ein neuer Punkt angelegt.",
  "Több számoló van egy helyen — víz, élelem, üzemanyag. Nincs külön csempéjük, mind itt található.": "Mehrere Rechner an einem Ort — Wasser, Essen, Kraftstoff. Sie haben keine eigene Kachel, alle sind hier.",
  "Új tételt a listához adsz: megadod, mi az, hova teszed, és mikor jár le.": "Du fügst der Liste einen neuen Eintrag hinzu: was es ist, wohin du es legst und wann es abläuft.",
  "A gombok be- és kikapcsolnak. Ugyanaz a gomb indítja és állítja le a jelzést.": "Die Tasten schalten ein und aus. Dieselbe Taste startet das Signal und stoppt es.",
  "A QR-kód a TELJES adatot viszi, nem egy linket. Ezért működik akkor is, ha nincs internet — a másik telefon a kódból olvassa ki.": "Der QR-Code trägt die VOLLSTÄNDIGEN Daten, keinen Link. Deshalb funktioniert er auch ohne Internet — das andere Telefon liest sie direkt aus dem Code.",
  "A vaku nem minden telefonon működik. Ha nem indul, használd a képernyő-fényt — az mindenhol megy.": "Der Blitz funktioniert nicht auf jedem Telefon. Wenn er nicht startet, nimm das Bildschirmlicht — das geht überall.",
  "A szám azt mutatja, mennyi áll a tárcádban.": "Die Zahl zeigt, wie viel in deiner Wallet steht.",
  "D": "S",
  "K": "O",
  "Ny": "W",
