  "Csak azzal számol, amit elbírsz: 1,5 liter fejenként. Ez túrához való, és a listán kiírom, mennyit kell útközben szerezni.": "Rechnet nur mit dem, was du tragen kannst: 1,5 Liter pro Person. Das ist für eine Tour gedacht, und in der Liste schreibe ich aus, wie viel unterwegs beschafft werden muss.",
