  "A víz csak az indulásra elég.": "Das Wasser reicht nur für den Aufbruch.",
  "napra valójában": "Tage werden tatsächlich",
  "liter kellene, ennyit viszont nem lehet elvinni.": "Liter gebraucht, so viel lässt sich aber nicht mitnehmen.",
  "liter, amit útközben kell megszerezni:": "Liter müssen unterwegs beschafft werden:",
  "vízszűrő, víztisztító tabletta, ismert vízvételi pont. Ezt a listán is nézd meg.": "Wasserfilter, Entkeimungstabletten, eine bekannte Wasserstelle. Sieh dir das auch in der Liste an.",
  "A készletedben most": "In deinem Vorrat sind derzeit",
  "kcal van megadva, ami ennek az útnak a": "kcal angegeben, was für diese Reise",
  "Hiányzik még kb.": "Es fehlen noch etwa",
  "Ez elég.": "Das reicht.",
  "tételnél nincs megadva az energia (kcal/100 g), azok nem számítanak bele. A dobozról leolvasva pontosabb lesz.": "Einträgen ist die Energie (kcal/100 g) nicht angegeben, sie werden nicht mitgerechnet. Von der Verpackung abgelesen wird es genauer.",
  "Ez nehezebb, mint amit el tudtok vinni. A kijelölt személyek együtt kb.": "Das ist schwerer, als ihr tragen könnt. Die markierten Personen schaffen zusammen etwa",
  "kg-ot bírnak, a lista": "kg, die Liste wiegt",
  "kg. A víz a legnehezebb: fontold meg a vízszűrőt kanna helyett, vagy vidd rövidebb szakaszra.": "kg. Wasser ist am schwersten: Überleg dir einen Wasserfilter statt des Kanisters, oder nimm es für eine kürzere Strecke mit.",
  "Belefér: a kijelöltek kb.": "Es passt: Die Markierten schaffen etwa",
  "kg-ot bírnak.": "kg.",
  "fő között: fejenként kb.": "Personen: pro Kopf etwa",
  "Nála:": "Bei ihm:",
  "kg (ebből": "kg (davon",
  "kg a sajátja": "kg eigenes",
  "kg a közösből": "kg aus dem Gemeinsamen",
  "· teherbírása": "· Tragfähigkeit",
  "— EZ TÖBB, MINT AMIT ELBÍR": "— DAS IST MEHR, ALS ER TRAGEN KANN",
  "— belefér": "— passt",
  "A hiányzik jelölésűek a beszerzési listád. Most": "Die mit „fehlt\" markierten Einträge sind deine Einkaufsliste. Derzeit gibt es",
  "ilyen van. A vizet és az élelmet a készlet KATEGÓRIÁJÁBÓL ismeri fel, a többit a nevéből.": "davon. Wasser und Essen erkennt es an der KATEGORIE des Vorrats, alles Übrige am Namen.",
  "A víz- és energia-számok tervezési értékek, nem orvosi előírás. A csecsemő és az állat külön normával számol.": "Die Wasser- und Energiewerte sind Planungswerte, keine ärztliche Vorgabe. Säugling und Tier werden nach eigener Norm gerechnet.",
  "Egy power station a telefont, a lámpát és egy rádiót is elviszi napokig. Kisebb igényre powerbank is elég.": "Eine Powerstation trägt Telefon, Lampe und ein Funkgerät tagelang. Bei geringerem Bedarf reicht auch eine Powerbank.",
  "Tűzifa, PB-palack vagy fűtőolaj — a kockázatelemzés kiszámolja, mennyi kell a megadott napokra.": "Brennholz, Gasflasche oder Heizöl — die Risikoanalyse berechnet, wie viel für die angegebenen Tage nötig ist.",
  "Kannás víz és víztisztító a legolcsóbb biztosíték. Egy IBC tartály hosszú távra megoldja.": "Kanisterwasser und ein Entkeimungsmittel sind die billigste Absicherung. Ein IBC-Tank löst es langfristig.",
  "Egy fejlámpa a legfontosabb: szabadon hagyja a kezed. Mellé egy tartalék elemkészlet.": "Am wichtigsten ist eine Stirnlampe: Sie lässt deine Hände frei. Dazu ein Satz Ersatzbatterien.",
  "A tárolt üzemanyag a fűtésnél is szerepel: ugyanaz a liter vagy fűt, vagy visz.": "Der gelagerte Kraftstoff taucht auch bei der Heizung auf: Derselbe Liter heizt entweder oder fährt.",
  "Ehhez a helyszínhez még nincs készlet rendelve, ezért nem tudjuk mérni. A Készletnél a tétel Tárolási helyénél tudod bejelölni.": "Diesem Ort ist noch kein Vorrat zugeordnet, deshalb können wir nichts messen. Zuordnen kannst du ihn im Bereich „Vorrat\", im Feld „Lagerort\" des Eintrags.",
  "Ehhez a helyszínhez nincs tétel rendelve. A Készletnél a tétel Tárolási helyénél tudod bejelölni.": "Diesem Ort ist kein Eintrag zugeordnet. Zuordnen kannst du ihn im Bereich „Vorrat\", im Feld „Lagerort\" des Eintrags.",
  ": nincs hatótáv — add meg a fogyasztást az adatlapján": ": keine Reichweite — gib den Verbrauch im Datenblatt an",
  "20000 = 20 liter (millilitert kérünk)": "20000 = 20 Liter (wir bitten um Milliliter)",
  "5000 = egy 5 literes kanna": "5000 = ein 5-Liter-Kanister",
  "1500 = másfél literes": "1500 = eineinhalb Liter",
  "100000 = egy mázsa": "100000 = ein Zentner",
  "11500 = egy 11,5 kg-os PB": "11500 = eine 11,5-kg-Gasflasche",
  ". Ez soknak tűnik. Biztos, hogy jó a mennyiség": ". Das wirkt viel. Sind die Menge",
  "és az egységnyi súly? (Egy IBC tartály például 1 darab, 1000 kg.) OK = mégis felveszem.": "und das Stückgewicht wirklich richtig? (Ein IBC-Tank ist zum Beispiel 1 Stück, 1000 kg.) OK = trotzdem hinzufügen.",
  "A vészkártyád (vércsoport, allergia, gyógyszerek, kontakt) itt jelenik meg gyorsan. Töltsd ki a Vészkártya szekcióban.": "Deine Notfallkarte (Blutgruppe, Allergie, Medikamente, Kontakt) erscheint hier schnell. Fülle sie im Abschnitt „Notfallkarte\" aus.",
  "pl. Amit hozz magaddal": "z. B. Was du mitbringen sollst",
  "víz 5 liter&#10;elemlámpa&#10;gyógyszerek": "Wasser 5 Liter&#10;Taschenlampe&#10;Medikamente",
  "Vízitúra": "Wassertour",
  "Őszi túra": "Herbsttour",
  "Nyári túra": "Sommertour",
  "Esőkabát": "Regenjacke",
  "Ehhez a helyszínhez még nincs készlet rendelve, ezért nem tudjuk mérni. A Készletnél a tétel Tárolási helyénél válaszd ki:": "Diesem Ort ist noch kein Vorrat zugeordnet, deshalb können wir nichts messen. Wähle im Bereich „Vorrat\", im Feld „Lagerort\" des Eintrags aus:",
  "élelmiszernél hiányzik az energia (kcal/100 g) — addig az étel „?”.": "Lebensmitteln fehlt die Energie (kcal/100 g) — bis dahin steht beim Essen „?”.",
  "Csak azzal számol, amit elbírsz: 1,5 liter fejenként. Ez túrához való, és a listán kiírom, mennyi hiányzik a teljes fejadaghoz.": "Rechnet nur mit dem, was du tragen kannst: 1,5 Liter pro Person. Das ist für eine Tour gedacht, und in der Liste schreibe ich aus, wie viel zur vollen Ration fehlt.",
  "tételnél nincs megadva az energia (kcal/100 g), azok nem számítanak bele. A dobozról leolvasva pontosabb lesz a kép.": "Einträgen ist die Energie (kcal/100 g) nicht angegeben, sie werden nicht mitgerechnet. Von der Verpackung abgelesen wird das Bild genauer.",
  "A víz- és energia-számok tervezési értékek, nem orvosi előírás. A csecsemő és az állat külön normán fut, nem a felnőtt arányosításából.": "Die Wasser- und Energiewerte sind Planungswerte, keine ärztliche Vorgabe. Säugling und Tier laufen nach eigener Norm, nicht anteilig vom Erwachsenen.",
  "fő ·": "Personen ·",
  "nap ·": "Tage ·",
  "fő/állat ·": "Personen/Tiere ·",
  "fő)": "Personen)",
  "Víz (": "Wasser (",
  "kg testtömegre)": "kg Körpergewicht)",
  "0,06 l/testtömeg-kg/nap": "0,06 l/kg Körpergewicht/Tag",
  "l/nap ×": "l/Tag ×",
