  "személyre szóló (": "pro Person (",
  ": be van írva a betegség (": ": Die Erkrankung ist eingetragen (",
  "fejenként egy (": "eines pro Person (",
  "— a": "— aus dem",
  "-es tank": "-Liter-Tank",
  "m² alapján": "auf Basis von m²",
  "%-a .": "% .",
  "a helyszín típusa szerint": "nach Art des Ortes",
  "kézzel megadott": "manuell angegeben",
  "kézzel megadott napi igény": "manuell angegebener Tagesbedarf",
  "itteni élelmiszernél hiányzik a súly vagy az energia (kcal/100 g), ezért nem számít bele. Nyisd meg a tételt a Készletnél, és írd be a doboz adatait.": "Lebensmitteln hier fehlt das Gewicht oder die Energie (kcal/100 g), deshalb werden sie nicht mitgerechnet. Öffne den Eintrag im Bereich „Vorrat\" und trag die Angaben von der Verpackung ein.",

  // --- POTLAS 2026-08-31 (Marveen): a het szotar osszevetesebol hianyzo kulcsok.
  // Az UKRAN valtozat volt az egyetlen teljes (1218 kulcs); ezek a tobbi hatbol
  // kimaradtak. Forditatlanul nem hibaznak, hanem MAGYARUL jelennek meg.
  "A szoba kulcsa": "Raumschlüssel",
