 "Ebben a böngészőben és iPhone-on az ébresztő nem tud megszólalni: a weboldal nem kapcsolhatja be a lezárt telefont. Az ébresztő az Android appban működik. A beállításod itt megmarad.": "In diesem Browser und auf dem iPhone kann der Wecker nicht klingeln: Eine Webseite kann ein gesperrtes Telefon nicht einschalten. Der Wecker funktioniert in der Android-App. Deine Einstellung bleibt hier gespeichert.",
 "Ehhez az ébresztőhöz frissítsd az appot a legújabb változatra.": "Aktualisiere die App auf die neueste Version, um diesen Wecker zu nutzen.",
 "Az értesítés nincs engedélyezve: enélkül az ébresztő nem tud megjelenni.": "Benachrichtigungen sind nicht erlaubt: Ohne sie kann der Wecker nicht erscheinen.",
 "Értesítés engedélyezése": "Benachrichtigungen erlauben",
 "A pontos időzítés nincs engedélyezve (Ébresztők és emlékeztetők): az ébresztő így akár negyed órát is késhet.": "Genaue Zeitplanung ist nicht erlaubt (Wecker und Erinnerungen): Der Wecker kann so bis zu einer Viertelstunde zu spät kommen.",
 "Pontos időzítés engedélyezése": "Genaue Zeitplanung erlauben",
 "A teljes képernyős értesítés nincs engedélyezve: lezárt telefonon csak értesítés jelenik meg, a felolvasás a koppintásra indul.": "Vollbild-Benachrichtigungen sind nicht erlaubt: Auf einem gesperrten Telefon erscheint nur eine Benachrichtigung, das Vorlesen beginnt beim Antippen.",
 "Teljes képernyő engedélyezése": "Vollbild erlauben",
