 "legalább 6 GB memória kell": "mindestens 6 GB Arbeitsspeicher sind nötig",
 "nem támogatott": "nicht unterstützt",
 "Ehhez a modellhez kevés a telefon memóriája.": "Für dieses Modell hat das Telefon zu wenig Arbeitsspeicher.",
