 "Memória: legalább {ajanlott} GB-os telefon ajánlott.": "Arbeitsspeicher: ein Telefon mit mindestens {ajanlott} GB wird empfohlen.",
 "Ez a telefon {ram} GB-os.": "Dieses Telefon hat {ram} GB.",
 "Most mobilinternetet használsz: a letöltés {meret} adatforgalom. Wi-Fi ajánlott.": "Du nutzt gerade mobile Daten: der Download sind {meret} Datenvolumen. WLAN wird empfohlen.",
 "Offline MI segéd": "Offline-KI-Assistent",
 "Offline MI segéd használata": "Offline-KI-Assistent verwenden",
 "A segéd a fejléc gombjával nyílik; a modell letöltése és a beállításai a segéd oldalán vannak.": "Der Assistent öffnet sich über die Schaltfläche in der Kopfzeile; der Modell-Download und seine Einstellungen sind auf der Seite des Assistenten.",
 "Offline MI segéd · a tudástárból, forrással": "Offline-KI-Assistent · aus der Wissensdatenbank, mit Quellen",
 "Kérdezz": "Frag",
 "Noah, az offline MI segéd": "Noah, der Offline-KI-Assistent",
 "Noah a telefonon futó MI segéd: a tudástárból, a Bibliából és az app adataidból válaszol, internet nélkül. A nyelvi modellt egyszer kell letölteni (2,6 vagy 3,7 GB). Letöltés előtt az app kiírja a méretet, a szükséges szabad helyet és memóriát, mobilinterneten pedig Wi-Fi-t javasol. 6 GB-nál kevesebb memóriájú telefonon nem használható, és ezt meg is indokolja.": "Noah ist der KI-Assistent auf dem Telefon: Er antwortet aus der Wissensdatenbank, der Bibel und deinen App-Daten, ohne Internet. Das Sprachmodell muss einmal heruntergeladen werden (2,6 oder 3,7 GB). Vor dem Download zeigt die App die Größe, den nötigen freien Speicher und Arbeitsspeicher, und bei mobilen Daten empfiehlt sie WLAN. Auf einem Telefon mit weniger als 6 GB Arbeitsspeicher ist er nicht nutzbar, und die App erklärt den Grund.",
 "Beállítások: kapcsold be az „Offline MI segéd használata” pontot, majd nyisd meg Noah-t a fejléc szikra gombjával.": "Einstellungen: schalte „Offline-KI-Assistent verwenden“ ein und öffne Noah dann mit der Funken-Schaltfläche in der Kopfzeile.",
 "A fogaskerék alatt nyomd meg a Letöltés gombot: nézd meg, kiírja-e a méretet, a helyet és a memóriát, mielőtt elindul. Wi-Fi-n töltsd le.": "Tippe unter dem Zahnrad auf Herunterladen: Prüfe, ob Größe, Speicherplatz und Arbeitsspeicher vor dem Start angezeigt werden. Lade es im WLAN herunter.",
 "Kérdezz tőle valamit, például: „Hogyan tisztítsak vizet?” Nézd meg, kapsz-e választ forrással.": "Frag ihn etwas, zum Beispiel: „Wie reinige ich Wasser?“ Prüfe, ob du eine Antwort mit Quelle bekommst.",
 "Ha a telefon nagy ütést érez, és utána egy percig nem mozdul, felkapcsolja a kijelzőt (lezárt telefonon is), és hangosan visszaszámol. Ha nem nyomod meg a": "Wenn das Telefon einen harten Stoß spürt und sich danach eine Minute nicht bewegt, schaltet es den Bildschirm ein (auch bei gesperrtem Telefon) und zählt laut herunter. Wenn du nicht auf",
 "Utána megszólal a vészsíp.": "Danach ertönt die Notpfeife.",
 "Esés-riasztás": "Sturzalarm",
 "%d másodperc múlva SOS üzenet megy a helyzeteddel. Ha jól vagy, nyomd meg: Jól vagyok.": "In %d Sekunden wird eine SOS-Nachricht mit deinem Standort gesendet. Wenn es dir gut geht, drücke: Mir geht es gut.",
 "Az értesítés nincs engedélyezve: enélkül esés után a lezárt telefonon nem jelenik meg a visszaszámlálás.": "Benachrichtigungen sind nicht erlaubt: ohne sie kann der Countdown nach einem Sturz auf dem gesperrten Telefon nicht erscheinen.",
 "A teljes képernyős értesítés nincs engedélyezve: esés után a lezárt telefonon csak egy értesítés jelenik meg a visszaszámlálással és a Jól vagyok gombbal, a nagy számláló koppintásra nyílik meg.": "Vollbild-Benachrichtigungen sind nicht erlaubt: nach einem Sturz zeigt das gesperrte Telefon nur eine Benachrichtigung mit dem Countdown und der Schaltfläche Mir geht es gut; der große Zähler öffnet sich beim Antippen.",
 "Esés után a lezárt telefonon is felkapcsolja a kijelzőt, és mutatja a visszaszámlálást.": "Nach einem Sturz schaltet es den Bildschirm ein, auch bei gesperrtem Telefon, und zeigt den Countdown.",
