 "Halk, ismétlődő zene a felolvasás alatt. Előbb töltsd le; utána internet nélkül is szól. A hangerejét felolvasás közben a hangjegy gombbal állíthatod.": "Leise, sich wiederholende Musik während des Vorlesens. Lade sie zuerst herunter; danach spielt sie auch ohne Internet. Die Lautstärke stellst du beim Vorlesen mit der Notentaste ein.",
